const initialRules:Rule[]=policyTexts.map((text,index)=>({id:101+index,text,uses:0,group:"Writing Tone"}));
const policyGroups=["Writing Tone","Accuracy & Facts","Language & Translation","Structure & Readability","Naming & Terminology","Formatting & CTA"];
function fallbackPolicyGroup(text:string){const value=text.toLocaleLowerCase("vi");if(/nguồn|dữ kiện|xác minh|fact|trích dẫn|tbc/.test(value))return "Accuracy & Facts";if(/dịch|tiếng việt|tiếng anh|english|ngôn ngữ/.test(value))return "Language & Translation";if(/tên|thuật ngữ|placeholder|nhất quán/.test(value))return "Naming & Terminology";if(/headline|mở bài|kết thúc|mạch|câu ngắn|ý lặp|cấu trúc/.test(value))return "Structure & Readability";if(/bullet|emoji|cta|caption|typography|định dạng/.test(value))return "Formatting & CTA";return "Writing Tone"}
const statusClass:Record<Status,string>={"Đang làm":"border-blue-200 bg-blue-50 text-blue-700","Chờ duyệt":"border-amber-200 bg-amber-50 text-amber-700","Đã xong":"border-emerald-200 bg-emerald-50 text-emerald-700"};
